const composeListNotifications = `-- name: ComposeListNotifications :many
SELECT notifications.id, notifications.kind, notifications.conversation_id, notifications.message_id,
    notifications.created_at, notifications.read_at,
    conversations.number AS conversation_number, conversations.subject AS conversation_subject,
    actors.id AS actor_id, actors.name AS actor_name
FROM notifications
JOIN conversations ON conversations.id = notifications.conversation_id AND conversations.deleted_at IS NULL
LEFT JOIN users AS actors ON actors.id = notifications.actor_id
WHERE notifications.user_id = $1
    AND conversations.mailbox_id = ANY($2::uuid[])
    AND (NOT $3::boolean OR notifications.read_at IS NULL)
ORDER BY notifications.created_at DESC, notifications.id DESC
LIMIT $4::integer
`

type ComposeListNotificationsParams struct {
	UserID     pgtype.UUID
	MailboxIds []pgtype.UUID
	UnreadOnly bool
	PageSize   int32
}

type ComposeListNotificationsRow struct {
	ID                  pgtype.UUID
	Kind                string
	ConversationID      pgtype.UUID
	MessageID           pgtype.UUID
	CreatedAt           pgtype.Timestamptz
	ReadAt              pgtype.Timestamptz
	ConversationNumber  int64
	ConversationSubject string
	ActorID             pgtype.UUID
	ActorName           pgtype.Text
}

// Hidden conversations are left out, so a notification never reveals one.
func (q *Queries) ComposeListNotifications(ctx context.Context, arg ComposeListNotificationsParams) ([]ComposeListNotificationsRow, error) {
	rows, err := q.db.Query(ctx, composeListNotifications,
		arg.UserID,
		arg.MailboxIds,
		arg.UnreadOnly,
		arg.PageSize,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ComposeListNotificationsRow{}
	for rows.Next() {
		var i ComposeListNotificationsRow
		if err := rows.Scan(
			&i.ID,
			&i.Kind,
			&i.ConversationID,
			&i.MessageID,
			&i.CreatedAt,
			&i.ReadAt,
			&i.ConversationNumber,
			&i.ConversationSubject,
			&i.ActorID,
			&i.ActorName,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

