const composeResolveSignature = `-- name: ComposeResolveSignature :one
SELECT body_html,
    CASE WHEN user_id IS NOT NULL AND mailbox_id IS NOT NULL THEN 'user_mailbox'
         WHEN user_id IS NOT NULL THEN 'user'
         ELSE 'mailbox' END::text AS source
FROM signatures
WHERE (user_id = $1 AND (mailbox_id = $2 OR mailbox_id IS NULL))
    OR (user_id IS NULL AND mailbox_id = $2)
ORDER BY (user_id IS NOT NULL AND mailbox_id IS NOT NULL) DESC, (user_id IS NOT NULL) DESC
LIMIT 1
`

type ComposeResolveSignatureParams struct {
	UserID    pgtype.UUID
	MailboxID pgtype.UUID
}

