func (q *Queries) ComposeResolveSignature(ctx context.Context, arg ComposeResolveSignatureParams) (ComposeResolveSignatureRow, error) {
	row := q.db.QueryRow(ctx, composeResolveSignature, arg.UserID, arg.MailboxID)
	var i ComposeResolveSignatureRow
	err := row.Scan(&i.BodyHtml, &i.Source)
	return i, err
}

